// js
// 勞工請假規則 §7: personal leave carries no wage.
// proration_basis CALENDAR_DAYS: a day is the month's wages ÷ the days of the period; the meal allowance falls with BASIC_AFTER_UNPAID_LEAVE.
// PAID so this line, not the salary basis, takes the days, and a reversal entry on this item pays them back.
const terms = ctx.subject.employment.terms;
if (['DAILY', 'HOURLY'].includes(get(terms, 'rate.unit', 'MONTHLY'))) return ctx.day_rate * ctx.entry.quantity;
const coverage = ctx.run.salary_coverage;
const slots = ctx.entry.days.map((day) => day.date);
const whole = slots
	.filter((date, index) => slots.indexOf(date) === index && slots.filter((other) => other === date).length > 1)
	.toSorted();
const scheduled = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
// The contract's working week answers where no roster does.
const week = Number(get(ctx.subject.employment.terms, 'normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const worksOn = (date) => {
	const day = ctx.work.days.find((row) => row.date === date);
	return day == null ? !off.includes(weekday(date)) : ['WORK', 'ABS'].includes(get(day, 'day_type', 'WORK'));
};
// a rest day between two missed work days is not earned
let rest = 0;
for (let index = 1; index < whole.length; index += 1) {
	let between = [];
	for (let step = 1; step < calendar_distance_days(whole[index - 1], whole[index]); step += 1)
		between = [...between, add_days(whole[index - 1], step)];
	if (between.length > 0 && !between.some(worksOn)) rest += between.length;
}
// A reversal gives back what the month before took, on that month's days.
const reversal = ctx.entry.is_reversal === true;
const back = add_days(coverage.from, -1);
const halves = get(ctx.subject.employer, 'payment_schedule.frequency', '') === 'SEMI_MONTHLY';
const from = !reversal ? coverage.from : halves && Number(String(back).slice(8, 10)) > 15 ? add_days(month_start(back), 15) : String(month_start(back));
const to = reversal ? back : coverage.to;
const monthDays = calendar_distance_days(from, to) + 1;
// a period with no work day left is not earned at all
let left = false;
for (let step = 0; step < monthDays; step += 1) {
	const date = add_days(from, step);
	if (worksOn(date) && !whole.includes(date)) left = true;
}
const pay = Number(get(terms, 'rate.amount', 0));
return (pay * (left ? Math.min(ctx.entry.quantity + rest, monthDays) : monthDays)) / monthDays;

// 勞動基準法 §50(2): full wages after six months' service, half before.
const earliest = ctx.entry.days.map((slot) => slot.date).toSorted()[0];
if (calendar_completed_months(ctx.subject.employment.effective_range.from, earliest) >= ctx.lookup.full_pay_service_months) return 0;
return ctx.day_rate * ctx.entry.quantity * ctx.lookup.half_pay_share;

