// 性別平等工作法 §16; 民法 §123(2): no wage for the stretch, on a 30-day month. PAID so this line, not the salary basis, takes the days: BASIC_AFTER_PARENTAL_LEAVE tells the premium rows how many (§16(2): employer share waived, worker's deferred).
if (get(ctx.subject.employment, 'terms.rate.unit', 'MONTHLY') !== 'MONTHLY') return Math.min(ctx.base_pay, ctx.day_rate * ctx.entry.quantity);
const dates = ctx.entry.days.map((slot) => slot.date).toSorted();
const last = dates.at(-1);
const first_day = Math.min(ctx.lookup.monthly_divisor, Number(dates[0].substring(8)));
const last_day = last === month_end(last) ? ctx.lookup.monthly_divisor : Number(last.substring(8));
return ctx.day_rate * (last_day - first_day + 1);

